const $=s=>document.querySelector(s);
let token='', messages=new Map(), offset=null, busy=false, generation=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=$('#search').value.toLocaleLowerCase('es');$('#messages').innerHTML=[...messages.values()].filter(m=>(m.name+' '+m.phone).toLocaleLowerCase('es').includes(q)).sort((a,b)=>b.at.localeCompare(a.at)).map(m=>`<article class="settings-card"><strong>${esc(m.name)}</strong> <span>${esc(m.phone)}</span><p style="white-space:pre-wrap">${esc(m.text)}</p><small>${esc(new Date(m.at).toLocaleString('es-PE'))}</small></article>`).join('')||'<p>No hay mensajes para mostrar.</p>';$('#more').classList.toggle('hidden',offset===null);}
async function load(older=false){if(busy)return;busy=true;const current=generation;$('#status').textContent='Consultando mensajes…';try{const r=await fetch('/api/whatsapp-inbox?offset='+(older?offset:0),{headers:{Authorization:'Bearer '+token},cache:'no-store',signal:AbortSignal.timeout(15000)});const data=await r.json();if(current!==generation)return;if(!r.ok)throw Error(data.error||'No se pudo abrir la bandeja.');for(const m of data.messages)messages.set(m.id,m);if(older||offset===null)offset=data.nextOffset;$('#login').classList.add('hidden');$('#controls').classList.remove('hidden');$('#status').textContent=messages.size+' mensajes cargados · '+new Date().toLocaleTimeString('es-PE');render();}catch(e){if(current===generation)$('#status').textContent=e.message;}finally{busy=false;}}
$('#login').onsubmit=e=>{e.preventDefault();token=$('#password').value;$('#password').value='';load();};
$('#refresh').onclick=()=>load();$('#more').onclick=()=>load(true);$('#search').oninput=render;
$('#logout').onclick=()=>{generation++;token='';messages.clear();offset=null;$('#messages').replaceChildren();$('#controls').classList.add('hidden');$('#more').classList.add('hidden');$('#login').classList.remove('hidden');$('#status').textContent='Acceso cerrado.';};
